// FindGameServer retrieves a single record by primary key
// If cols is empty Find will return all columns.
func FindGameServer(ctx context.Context, exec bob.Executor, IDPK string, cols ...string) (*GameServer, error) {
	if len(cols) == 0 {
		return GameServers.Query(
			sm.Where(GameServers.Columns.ID.EQ(sqlite.Arg(IDPK))),
		).One(ctx, exec)
	}

	return GameServers.Query(
		sm.Where(GameServers.Columns.ID.EQ(sqlite.Arg(IDPK))),
		sm.Columns(GameServers.Columns.Only(cols...)),
	).One(ctx, exec)
}

// GameServerExists checks the presence of a single record by primary key
func GameServerExists(ctx context.Context, exec bob.Executor, IDPK string) (bool, error) {
	return GameServers.Query(
		sm.Where(GameServers.Columns.ID.EQ(sqlite.Arg(IDPK))),
	).Exists(ctx, exec)
}

// AfterQueryHook is called after GameServer is retrieved from the database
func (o *GameServer) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = GameServers.AfterSelectHooks.RunHooks(ctx, exec, GameServerSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = GameServers.AfterInsertHooks.RunHooks(ctx, exec, GameServerSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = GameServers.AfterUpdateHooks.RunHooks(ctx, exec, GameServerSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = GameServers.AfterDeleteHooks.RunHooks(ctx, exec, GameServerSlice{o})

	}

	return err
}

// primaryKeyVals returns the primary key values of the GameServer
func (o *GameServer) primaryKeyVals() bob.Expression {
	return sqlite.Arg(o.ID)
}

func (o *GameServer) pkEQ() dialect.Expression {
	return sqlite.Quote("game_server", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		return o.primaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

// Update uses an executor to update the GameServer
func (o *GameServer) Update(ctx context.Context, exec bob.Executor, s *GameServerSetter) error {
	v, err := GameServers.Update(s.UpdateMod(), um.Where(o.pkEQ())).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R = v.R
	*o = *v

	return nil
}

// Delete deletes a single GameServer record with an executor
func (o *GameServer) Delete(ctx context.Context, exec bob.Executor) error {
	_, err := GameServers.Delete(dm.Where(o.pkEQ())).Exec(ctx, exec)
	return err
}

// Reload refreshes the GameServer using the executor
func (o *GameServer) Reload(ctx context.Context, exec bob.Executor) error {
	o2, err := GameServers.Query(
		sm.Where(GameServers.Columns.ID.EQ(sqlite.Arg(o.ID))),
	).One(ctx, exec)
	if err != nil {
		return err
	}
	o2.R = o.R
	*o = *o2

	return nil
}

