func (o GameServerSlice) UpdateAll(ctx context.Context, exec bob.Executor, vals GameServerSetter) error {
	if len(o) == 0 {
		return nil
	}

	_, err := GameServers.Update(vals.UpdateMod(), o.UpdateMod()).All(ctx, exec)
	return err
}

func (o GameServerSlice) DeleteAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	_, err := GameServers.Delete(o.DeleteMod()).Exec(ctx, exec)
	return err
}

func (o GameServerSlice) ReloadAll(ctx context.Context, exec bob.Executor) error {
	if len(o) == 0 {
		return nil
	}

	o2, err := GameServers.Query(sm.Where(o.pkIN())).All(ctx, exec)
	if err != nil {
		return err
	}

	o.copyMatchingRows(o2...)

	return nil
}

